window.AA_DATA = {"site": {"name": "Alpine Ascents", "tagline": "Know the mountain before you climb it", "hero": {"title": "Climb smart. Come back down.", "text": "Alpine Ascents is a guide to mountaineering for people who want the real picture: where it came from, how it is done, what can go wrong and who to climb with. Pick a topic from the menu or start with the story below.", "image": "assets/img/everest-dawn.svg"}, "facts": [{"label": "Highest point on land", "value": "8,849 m", "note": "Mount Everest, Nepal and China"}, {"label": "First ascent of Everest", "value": "1953", "note": "Hillary and Tenzing, 29 May"}, {"label": "Everest summits, spring 2026", "value": "879+", "note": "busiest season on record"}, {"label": "Oldest alpine club", "value": "1857", "note": "The Alpine Club, London"}], "cards": [{"route": "history", "title": "History", "icon": "bi-hourglass-split", "text": "From Mont Blanc in 1786 to the Sherpa climbers who set today's records.", "img": "assets/img/history-engraving.svg"}, {"route": "styles", "title": "Types and Styles", "icon": "bi-diagram-3", "text": "Alpine style, expedition style, ice, rock, ski. They are not the same sport.", "img": "assets/img/ice-climbing.svg"}, {"route": "techniques", "title": "Techniques", "icon": "bi-bezier2", "text": "Ropework, crampons, self-arrest, glacier travel and how to pace a long day.", "img": "assets/img/glacier-team.svg"}, {"route": "shelter", "title": "Sheltering", "icon": "bi-house-door", "text": "Tents, bivouacs, snow caves and the huts that keep people alive.", "img": "assets/img/high-camp.svg"}, {"route": "hazards", "title": "Hazards", "icon": "bi-exclamation-triangle", "text": "Altitude, avalanches, cold, crevasses and weather, and what to do about each.", "img": "assets/img/k2-storm.svg"}, {"route": "records", "title": "Records", "icon": "bi-trophy", "text": "The fourteen 8,000 m peaks, the Seven Summits and the people behind the numbers.", "img": "assets/img/summit-ridge.svg"}, {"route": "clubs", "title": "Clubs and Map", "icon": "bi-geo-alt", "text": "Mountaineering clubs around the world, on a map, with distances from you.", "img": "assets/img/mountain-hut.svg"}, {"route": "stories", "title": "Success Stories", "icon": "bi-flag", "text": "Expeditions that worked, and what the people involved learned.", "img": "assets/img/prayer-flags.svg"}, {"route": "gallery", "title": "Gallery", "icon": "bi-images", "text": "Pictures and short explainer videos.", "img": "assets/img/denali-aurora.svg"}, {"route": "latest", "title": "Latest Developments", "icon": "bi-newspaper", "text": "New rules on Everest, a record season, and skimo at the Olympics.", "img": "assets/img/matterhorn-noon.svg"}, {"route": "guidelines", "title": "Guidelines", "icon": "bi-clipboard-check", "text": "A plain checklist for planning a first serious climb.", "img": "assets/img/aconcagua-dusk.svg"}]}, "history": {"intro": "People have been walking up mountains for as long as there have been mountains, but mountaineering as a sport, climbing because you want to, is much younger. Most historians put the start at the late 1700s, when a few curious people in the Alps began to treat the summits as something worth reaching.", "image": "assets/img/history-engraving.svg", "eras": [{"name": "Early ascents", "years": "1300s to 1700s", "items": [{"year": "1336", "title": "Petrarch on Mont Ventoux", "text": "The Italian poet Petrarch is said to have climbed Mont Ventoux in France just to look at the view. It is not a hard climb, but people still cite it as one of the first ascents made for its own sake."}, {"year": "1492", "title": "Mont Aiguille", "text": "King Charles VIII of France ordered his officer Antoine de Ville to climb Mont Aiguille. His party used ladders and ropes, so many see this as the first real technical climb."}, {"year": "1786", "title": "Mont Blanc", "text": "On 8 August, Jacques Balmat and Michel-Gabriel Paccard reached the top of Mont Blanc (4,808 m), the highest peak in the Alps. The scientist Horace-Bénédict de Saussure had offered a prize for it, and he climbed it himself the next year."}]}, {"name": "The Golden Age of Alpinism", "years": "1854 to 1865", "items": [{"year": "1854", "title": "Wetterhorn", "text": "Alfred Wills climbs the Wetterhorn in Switzerland. British climbers, often with local guides, then begin to claim the great Alpine summits one after another."}, {"year": "1857", "title": "The Alpine Club", "text": "The Alpine Club is founded in London. It is the oldest mountaineering club in the world. Swiss and Italian clubs follow in 1863."}, {"year": "1865", "title": "Matterhorn", "text": "Edward Whymper's party reaches the Matterhorn on 14 July. Four of the seven climbers fall to their deaths on the way down. The accident shocked Europe and started the first serious public argument about whether climbing was worth the risk."}]}, {"name": "Going higher", "years": "1900s to 1950s", "items": [{"year": "1924", "title": "Mallory and Irvine", "text": "George Mallory and Andrew Irvine disappear high on Everest on 8 June. Whether they reached the top before they died is still debated. Mallory's body was found in 1999."}, {"year": "1938", "title": "Eiger north face", "text": "Anderl Heckmair, Ludwig Vörg, Heinrich Harrer and Fritz Kasparek complete the first ascent of the Eiger's north face. Several climbers had died trying before them."}, {"year": "1950", "title": "Annapurna", "text": "Maurice Herzog and Louis Lachenal of France reach the top of Annapurna I on 3 June. It is the first of the fourteen 8,000 m peaks to be climbed."}, {"year": "1953", "title": "Everest", "text": "Edmund Hillary of New Zealand and Tenzing Norgay, a Sherpa from Nepal, stand on top of Everest on 29 May at the end of a large British expedition led by John Hunt."}, {"year": "1954", "title": "K2", "text": "Achille Compagnoni and Lino Lacedelli of Italy summit K2 on 31 July. K2 is lower than Everest but far harder and more dangerous."}]}, {"name": "Lighter, faster, bolder", "years": "1970s to 2000s", "items": [{"year": "1975", "title": "Junko Tabei", "text": "Junko Tabei of Japan becomes the first woman to climb Everest, on 16 May, only twelve days after an avalanche buried her at Camp II."}, {"year": "1978", "title": "No bottled oxygen", "text": "Reinhold Messner and Peter Habeler climb Everest without supplementary oxygen. Many doctors of the time had said it could not be done."}, {"year": "1986", "title": "All fourteen", "text": "Messner finishes all fourteen 8,000 m peaks, the first person to do so, with no bottled oxygen on any of them."}, {"year": "1996", "title": "A bad May on Everest", "text": "A storm on 10 and 11 May kills eight people on the mountain in one day. The accident, and the books written about it, changed how the public sees commercial guiding."}]}, {"name": "Now", "years": "2010 to today", "items": [{"year": "2019", "title": "Project Possible", "text": "Nirmal Purja of Nepal climbs all fourteen 8,000 m peaks in six months and six days. The earlier record was a little under eight years."}, {"year": "2021", "title": "K2 in winter", "text": "On 16 January ten Nepali climbers make the first winter ascent of K2, the last 8,000 m peak to be climbed in winter."}, {"year": "2023", "title": "Fourteen in 92 days", "text": "Kristin Harila of Norway and Tenjen Lama Sherpa finish the fourteen peaks in 92 days."}, {"year": "2026", "title": "A record spring", "text": "Kami Rita Sherpa reaches the top of Everest for the 32nd time on 17 May. The season sets records for permits and total summits."}]}]}, "styles": {"intro": "People say 'mountaineering' as if it were one activity. In practice it covers several styles that call for different skills, gear and attitudes to risk. Most climbers mix them over the years.", "styles": [{"name": "Alpine style", "icon": "bi-lightning-charge", "summary": "Go light, go fast, and do it in one push. No fixed camps, no fixed ropes, no porters carrying loads for you.", "good": "Fast, low impact, and the most respected way to do hard routes.", "bad": "Little margin. If the weather turns you have little food, little fuel and a long way down.", "example": "Climbing the Matterhorn from a hut in the Alps in a single day."}, {"name": "Expedition style", "icon": "bi-buildings", "summary": "Also called siege style. A team builds a chain of camps up the mountain and ferries food and gear up over several weeks.", "good": "Makes very high mountains possible for large teams and gives plenty of time to acclimatise.", "bad": "Costs more, needs more people, and leaves more rubbish if the team is careless.", "example": "Everest from the Nepal side, with Base Camp and four camps above it."}, {"name": "Rock climbing", "icon": "bi-bricks", "summary": "Moving up rock using hands and feet, with ropes and protection for safety. Grades run from easy scrambles to near-impossible overhangs.", "good": "Easy to practise close to home, and the skills carry over to big mountains.", "bad": "Rock on a big mountain is loose, cold and wet, which makes it very different from a gym or a crag.", "example": "The Hornbein Couloir or the rock bands on Everest's north side."}, {"name": "Ice and mixed climbing", "icon": "bi-snow2", "summary": "Climbing frozen waterfalls, glacier ice and snow-covered rock with two ice tools and crampons.", "good": "Opens the winter season and many of the world's classic north faces.", "bad": "Conditions change from day to day. A route that is good in January can be gone by March.", "example": "The north face of the Eiger, or a grade WI4 waterfall."}, {"name": "Glacier and snow climbing", "icon": "bi-cloud-snow", "summary": "Roped travel over glaciers and snow slopes to non-technical summits. This is how most people start.", "good": "A good first step into high mountains without needing hard climbing skills.", "bad": "Crevasses and avalanches are real hazards even on easy ground.", "example": "Mont Blanc by the standard route, or Kilimanjaro's upper slopes."}, {"name": "Ski mountaineering", "icon": "bi-wind", "summary": "Climb on skis with climbing skins, then take them off and ski down. A new Olympic sport since 2026, which is why you will hear 'skimo' more often.", "good": "Fast descents, and a long season in the Alps and the Rockies.", "bad": "You need both decent skiing and decent avalanche judgment.", "example": "The Haute Route from Chamonix to Zermatt."}, {"name": "Guided climbing", "icon": "bi-people", "summary": "A qualified guide leads and makes the decisions. Many people do their first big peaks this way.", "good": "A good way to learn, and the sensible choice on unfamiliar high mountains.", "bad": "Guided does not mean safe. You are still responsible for your own fitness and for speaking up.", "example": "A guided ascent of Aconcagua or Denali."}, {"name": "Solo climbing", "icon": "bi-person", "summary": "Climbing alone, sometimes with a rope for protection, sometimes without ('free solo').", "good": "Complete independence.", "bad": "Nobody to rescue you. Some countries now restrict solo climbs on their biggest peaks.", "example": "Messner's solo Everest climb in 1980."}], "grades": {"title": "How climbs are graded", "text": "No single grading system covers everything. These are the ones you will meet most often. Grades are opinions, so always check a local guidebook.", "rows": [{"system": "Alpine overall (French)", "scale": "F, PD, AD, D, TD, ED", "meaning": "From 'easy' (F) through 'a bit difficult' (PD) up to 'extremely difficult' (ED). Covers the whole route, not only the hardest move."}, {"system": "Rock (UIAA)", "scale": "I to XII", "meaning": "Roman numerals used across Europe. Grade V is where most beginners stop being comfortable."}, {"system": "Rock (Yosemite, YDS)", "scale": "5.0 to 5.15", "meaning": "Used in North America. 5.10 and up is hard rock climbing."}, {"system": "Water ice", "scale": "WI1 to WI7", "meaning": "WI1 is a frozen stream you can walk up. WI5 and up is steep, thin and serious."}, {"system": "Snow slope", "scale": "Angle in degrees", "meaning": "Avalanche risk is highest on slopes around 30 to 45 degrees."}]}}, "techniques": {"intro": "Good technique is mostly about doing small things correctly, every time, even when you are tired and cold. These are the basics every climber should be able to do without thinking.", "items": [{"name": "Moving with an ice axe", "cat": "Snow and ice", "icon": "bi-tools", "summary": "Your axe is a walking stick, a brake and a belay anchor.", "steps": ["Hold the axe in the uphill hand on a slope so you can use the pick to brake.", "Plunge the shaft in all the way before each step on steep snow.", "Keep your weight over your feet and your balance low.", "Practise the positions on a safe slope before you ever need them."]}, {"name": "Self-arrest", "cat": "Snow and ice", "icon": "bi-brake-warning", "summary": "How to stop yourself after a slip on a snow slope. It has to be automatic.", "steps": ["Roll onto your front so the pick is under your chest, one hand on the head of the axe and one on the shaft.", "Dig the pick in with your body weight over it.", "Lift your hips and spread your feet; keep your crampons off the snow so they do not catch.", "Hold on until you stop, then get up carefully."]}, {"name": "Crampon technique", "cat": "Snow and ice", "icon": "bi-gear", "summary": "Steel spikes under your boots that turn ice into a staircase.", "steps": ["Flat-footing: put all the points in at once on moderate slopes, ankles bent.", "Front-pointing: kick the front points in for steep ice and keep your heels low.", "Walk with feet slightly apart so the points do not snag your trouser legs.", "Remove crampons on rock; they slip and they wear the points."]}, {"name": "Rope team travel", "cat": "Glaciers", "icon": "bi-link-45deg", "summary": "Climbers tied together over a glacier so one fall does not become a disaster.", "steps": ["Space the climbers around 8 to 12 m apart with the rope tight enough not to drag on the snow.", "Carry a few coils in your hand or pack for emergencies.", "Keep the rope off the snow behind you so it does not catch crevasse edges.", "Never untie on a glacier until you are well off it."]}, {"name": "Crevasse rescue", "cat": "Glaciers", "icon": "bi-arrow-down-up", "summary": "If a teammate falls into a crevasse, the rest of the team has to get them out.", "steps": ["Brace at once and drop into the self-arrest position when someone falls.", "Build an anchor in the snow, move the load onto it, then talk to the person who fell.", "Set up a pulley system (a 3:1 or 'Z-pulley') to haul them out.", "Practise this with your own team in daylight before you need it."]}, {"name": "Belaying and rappelling", "cat": "Rope work", "icon": "bi-diagram-2", "summary": "Controlling the rope for a climber, and getting down without the rope failing.", "steps": ["Check the knot, harness and belay device every time. A buddy check takes five seconds.", "Keep the brake hand on the rope at all times.", "For a rappel, back up with a prusik or autoblock below the device.", "Knot the ends of the ropes so you cannot slide off the end."]}, {"name": "Anchors", "cat": "Rope work", "icon": "bi-pin-angle", "summary": "Whatever you clip into has to hold a fall. Anchors are built from several pieces, never one.", "steps": ["Use at least two or three independent points: rock, ice screws, snow pickets or trees.", "Equalise them so the load is shared.", "Test by pulling hard in the direction of a fall.", "Do not trust old slings and old bolts without checking."]}, {"name": "Acclimatisation", "cat": "Altitude", "icon": "bi-graph-up-arrow", "summary": "The body needs days to adapt to thin air. There is no way to rush it.", "steps": ["Above about 3,000 m, raise your sleeping altitude by 300 to 500 m a day.", "Take a rest day every 3 to 4 days.", "Climb high, sleep low: go up during the day, return lower to sleep.", "Drink plenty of water and eat, even when you have no appetite."]}, {"name": "Pacing and breathing", "cat": "Altitude", "icon": "bi-speedometer2", "summary": "Climbers who go too fast early are the ones who stall at the top.", "steps": ["Use the rest step on steep ground: lock your back knee for a second between steps.", "Match your breathing to your steps; use pressure breathing (strong out-breath) at height.", "Keep a pace where you could still hold a conversation.", "Set a turnaround time before you leave and keep to it."]}, {"name": "Layering", "cat": "Staying warm", "icon": "bi-thermometer-half", "summary": "Three layers you can add and take off, so you never sweat and then freeze.", "steps": ["Base layer that moves sweat away from your skin.", "Insulation layer: fleece or a synthetic or down jacket.", "Shell layer that blocks wind and water.", "Take a layer off before you sweat, not after."]}, {"name": "Navigation", "cat": "Route finding", "icon": "bi-compass", "summary": "A whiteout takes away the horizon. Plan ahead because you will not see where you are going.", "steps": ["Carry a map, compass and a GPS or phone with offline maps. Learn to use all three.", "Take compass bearings and mark waypoints on the way up, so you can find the same line back down.", "Note landmarks and wand markers on the descent.", "If visibility drops and you cannot navigate, stop and wait."]}, {"name": "Avalanche safety", "cat": "Snow safety", "icon": "bi-broadcast", "summary": "Most avalanche victims trigger the slide themselves. Read the forecast and carry the right kit.", "steps": ["Read the avalanche bulletin the night before and again in the morning.", "Everyone carries a transceiver, probe and shovel, and knows how to use them.", "Cross suspect slopes one at a time, and avoid the 30 to 45 degree slopes after fresh snow.", "If caught, try to swim and keep a hand over your mouth to make an air pocket."]}]}, "shelter": {"intro": "Sleeping well on a mountain is part of climbing it. A good shelter keeps you dry, out of the wind and rested enough to make good decisions the next day.", "items": [{"name": "Mountaineering tent", "icon": "bi-triangle", "text": "A strong, low tent built to take wind and snow loading. Double-wall tents are warmer and have less condensation. Single-wall tents are lighter.", "tips": ["Pitch with the narrow end into the wind.", "Dig the platform flat and build snow walls on the windward side.", "Keep the vents open even if it is cold, to limit condensation."], "img": "assets/img/high-camp.svg"}, {"name": "Bivouac", "icon": "bi-moon-stars", "text": "Sleeping out with only a bivy bag, a sleeping bag and what you carry. Most often an emergency, sometimes a plan.", "tips": ["Find a ledge out of rockfall and wind.", "Keep your boots and gloves inside the bag so they do not freeze.", "Eat and drink before you settle in."], "img": "assets/img/summit-ridge.svg"}, {"name": "Snow cave", "icon": "bi-snow", "text": "Dug into a deep, stable snow drift. Surprisingly warm and quiet, with temperatures near freezing even when it is far colder outside.", "tips": ["Dig a sleeping platform higher than the entrance so cold air stays below.", "Make a ventilation hole in the roof and keep the entrance clear.", "Keep your shovel inside with you."], "img": "assets/img/ice-climbing.svg"}, {"name": "Igloo and quinzhee", "icon": "bi-house", "text": "An igloo is cut from blocks of firm snow. A quinzhee is a mound of snow that has set and been hollowed out. Both are slow to build but make a solid winter shelter.", "tips": ["Allow a few hours to build.", "Wait for a quinzhee mound to harden before digging.", "Mind the ventilation."], "img": "assets/img/glacier-team.svg"}, {"name": "Mountain huts and refuges", "icon": "bi-house-heart", "text": "The Alps have a network of staffed huts, which makes multi-day trips possible without carrying a tent. The Capanna Regina Margherita, at 4,554 m on the Italian-Swiss border, is the highest hut in Europe.", "tips": ["Book ahead in summer.", "Bring a sleeping bag liner, earplugs and a head torch.", "Leave early; most climbers set off before dawn."], "img": "assets/img/mountain-hut.svg"}, {"name": "Base camp and high camps", "icon": "bi-buildings", "text": "On big expeditions, Base Camp is a small town of tents with kitchen, dining and communications. Higher camps are small and basic, used only for a night or two.", "tips": ["Camp away from avalanche paths and icefall.", "Treat waste properly. Many camps now require you to carry it down.", "Tie down everything; a high-camp wind can take a tent."], "img": "assets/img/prayer-flags.svg"}], "checklist": ["Pick a site that is flat, out of the wind and away from avalanche runouts, rockfall and cornices.", "Anchor every guy line with snow stakes, buried axes or rocks.", "Ventilate any enclosed shelter. Carbon monoxide from a stove can kill.", "Never cook inside a closed tent without ventilation, and never sleep with a stove burning.", "Melt snow for water before you rest. Dehydration slows recovery."]}, "hazards": {"intro": "Mountains have two kinds of danger. Objective hazards, like avalanches and rockfall, are there whether or not you are. Subjective hazards come from us: poor planning, fatigue, ego, a group that will not turn back. Most accidents involve both.", "items": [{"name": "Altitude illness", "type": "Objective", "risk": 5, "icon": "bi-lungs", "summary": "Acute mountain sickness (AMS) can begin from about 2,500 m. Left alone it can become HAPE (fluid in the lungs) or HACE (swelling of the brain), both of which are fatal.", "signs": "Headache, nausea, dizziness, poor sleep. Warning signs of the severe forms: breathlessness at rest, a wet cough, confusion, loss of balance.", "prevent": "Ascend slowly, rest days, drink water, avoid alcohol and sleeping pills.", "response": "Stop climbing up. If symptoms are worsening, descend at once. Descent is the main treatment, with oxygen and medical help."}, {"name": "Avalanche", "type": "Objective", "risk": 5, "icon": "bi-cloud-snow", "summary": "A slab of snow breaks loose and slides. Most victims are caught on 30 to 45 degree slopes.", "signs": "Fresh heavy snowfall, wind loading, cracks shooting out from your feet, a 'whumpf' sound.", "prevent": "Check the bulletin. Avoid steep slopes after snow or sun. Cross one at a time.", "response": "Companions search first, using the transceiver, probe and shovel. Chances of survival fall quickly after about fifteen minutes."}, {"name": "Hypothermia", "type": "Objective", "risk": 4, "icon": "bi-thermometer-snow", "summary": "Body temperature falls below 35 °C. Wet clothes and wind make it far more likely.", "signs": "Shivering, then clumsiness, slurred speech, apathy. Shivering stopping in a cold person is a bad sign.", "prevent": "Layer well, stay dry, eat and drink often, shelter from wind.", "response": "Get out of the wind, replace wet clothing, insulate from the ground, give warm sweet drinks if the person is alert, and call for help."}, {"name": "Frostbite", "type": "Objective", "risk": 4, "icon": "bi-snow3", "summary": "Tissue freezes, usually fingers, toes, nose and ears.", "signs": "Numb, white or waxy skin that feels hard.", "prevent": "Keep extremities covered and dry. Loosen tight boots. Check partners' faces.", "response": "Do not rub. Rewarm in warm (not hot) water only if there is no chance of it freezing again, then seek medical care."}, {"name": "Crevasses", "type": "Objective", "risk": 4, "icon": "bi-slash-circle", "summary": "Cracks in glacier ice, often hidden under snow bridges that weaken as the day warms.", "signs": "Slight dips or sagging lines in the snow, especially where a glacier bends.", "prevent": "Rope up, move early in the day while the snow is firm, probe when unsure.", "response": "Brace and arrest the fall, anchor, then haul the climber out with a pulley system."}, {"name": "Weather", "type": "Objective", "risk": 5, "icon": "bi-cloud-lightning-rain", "summary": "Storms, whiteouts, lightning and wind can arrive quickly and make a simple route dangerous.", "signs": "Lenticular clouds, a sudden drop in pressure, building cloud, rising wind.", "prevent": "Check forecasts from several sources and start early so you are down before the afternoon.", "response": "Turn back early. Get off ridges and summits if there is lightning, and take shelter in a hollow with your pack under you."}, {"name": "Rockfall and icefall", "type": "Objective", "risk": 3, "icon": "bi-bricks", "summary": "Stones and ice blocks fall from above, often set off by the sun, other climbers, or animals.", "signs": "Debris at the foot of a slope, whistling, the sound of stones.", "prevent": "Wear a helmet. Move under dangerous ground quickly and early.", "response": "Shout 'ROCK!' and take cover. Never stop in a gully."}, {"name": "Sun and snow blindness", "type": "Objective", "risk": 2, "icon": "bi-sun", "summary": "UV radiation is stronger at height, and snow reflects it. Burned corneas are very painful.", "signs": "Gritty, watery eyes several hours after exposure.", "prevent": "Wear category 4 glacier glasses and sun cream, even on cloudy days.", "response": "Rest in a dark place; cool compresses. Carry a spare pair of dark glasses."}, {"name": "Fatigue and poor decisions", "type": "Subjective", "risk": 5, "icon": "bi-person-exclamation", "summary": "Most fatal accidents on big mountains happen on the way down, when people are exhausted and past their limits.", "signs": "Clumsy footwork, forgetting to eat or drink, tunnel vision on the summit.", "prevent": "Set a turnaround time and obey it. Agree that anyone can call off the climb.", "response": "Turn around. The summit is optional; getting down is not."}], "zones": [{"band": "Up to 2,500 m", "name": "Low altitude", "note": "Most people feel fine. Some mild breathlessness."}, {"band": "2,500 to 3,500 m", "name": "Moderate", "note": "AMS can begin. Rest days matter from here."}, {"band": "3,500 to 5,500 m", "name": "High", "note": "AMS common. HAPE and HACE are real risks if you go up too fast."}, {"band": "5,500 to 8,000 m", "name": "Very high", "note": "Few people stay here for long. Weight loss and poor sleep."}, {"band": "Above 8,000 m", "name": "The 'death zone'", "note": "Air pressure about a third of sea level. The body cannot acclimatise fully. Most people use bottled oxygen."}]}, "records": {"intro": "Records are a fun way into the sport, but they change. Where a record has moved in the last few years, the date is shown. Heights are rounded to the nearest metre.", "asOf": "Spring 2026 season", "peaks": [{"name": "Mount Everest", "height": 8849, "country": "Nepal / China", "first": 1953, "team": "Edmund Hillary, Tenzing Norgay"}, {"name": "K2", "height": 8611, "country": "Pakistan / China", "first": 1954, "team": "Achille Compagnoni, Lino Lacedelli"}, {"name": "Kangchenjunga", "height": 8586, "country": "Nepal / India", "first": 1955, "team": "Joe Brown, George Band"}, {"name": "Lhotse", "height": 8516, "country": "Nepal / China", "first": 1956, "team": "Ernst Reiss, Fritz Luchsinger"}, {"name": "Makalu", "height": 8485, "country": "Nepal / China", "first": 1955, "team": "Lionel Terray, Jean Couzy"}, {"name": "Cho Oyu", "height": 8188, "country": "Nepal / China", "first": 1954, "team": "Herbert Tichy, Sepp Jöchler, Pasang Dawa Lama"}, {"name": "Dhaulagiri I", "height": 8167, "country": "Nepal", "first": 1960, "team": "An international team led by Max Eiselin"}, {"name": "Manaslu", "height": 8163, "country": "Nepal", "first": 1956, "team": "Toshio Imanishi, Gyalzen Norbu"}, {"name": "Nanga Parbat", "height": 8126, "country": "Pakistan", "first": 1953, "team": "Hermann Buhl (solo)"}, {"name": "Annapurna I", "height": 8091, "country": "Nepal", "first": 1950, "team": "Maurice Herzog, Louis Lachenal"}, {"name": "Gasherbrum I", "height": 8080, "country": "Pakistan / China", "first": 1958, "team": "Pete Schoening, Andy Kauffman"}, {"name": "Broad Peak", "height": 8051, "country": "Pakistan / China", "first": 1957, "team": "Marcus Schmuck, Fritz Wintersteller, Kurt Diemberger, Hermann Buhl"}, {"name": "Gasherbrum II", "height": 8035, "country": "Pakistan / China", "first": 1956, "team": "Fritz Moravec, Josef Larch, Hans Willenpart"}, {"name": "Shishapangma", "height": 8027, "country": "China (Tibet)", "first": 1964, "team": "A Chinese expedition led by Xu Jing"}], "seven": [{"name": "Mount Everest", "height": 8849, "continent": "Asia", "first": 1953, "country": "Nepal / China"}, {"name": "Aconcagua", "height": 6961, "continent": "South America", "first": 1897, "country": "Argentina"}, {"name": "Denali", "height": 6190, "continent": "North America", "first": 1913, "country": "USA (Alaska)"}, {"name": "Kilimanjaro", "height": 5895, "continent": "Africa", "first": 1889, "country": "Tanzania"}, {"name": "Elbrus", "height": 5642, "continent": "Europe", "first": 1874, "country": "Russia"}, {"name": "Vinson Massif", "height": 4892, "continent": "Antarctica", "first": 1966, "country": "Antarctica"}, {"name": "Puncak Jaya", "height": 4884, "continent": "Oceania", "first": 1962, "country": "Indonesia (Papua)"}], "firsts": [{"year": 1786, "what": "First ascent of Mont Blanc", "who": "Jacques Balmat, Michel-Gabriel Paccard"}, {"year": 1950, "what": "First 8,000 m peak (Annapurna I)", "who": "Maurice Herzog, Louis Lachenal"}, {"year": 1953, "what": "First ascent of Everest", "who": "Edmund Hillary, Tenzing Norgay"}, {"year": 1975, "what": "First woman on Everest", "who": "Junko Tabei"}, {"year": 1978, "what": "First Everest ascent without bottled oxygen", "who": "Reinhold Messner, Peter Habeler"}, {"year": 1980, "what": "First winter ascent of Everest", "who": "Leszek Cichy, Krzysztof Wielicki"}, {"year": 1980, "what": "First solo Everest ascent", "who": "Reinhold Messner"}, {"year": 1986, "what": "First to climb all fourteen 8,000 m peaks", "who": "Reinhold Messner"}, {"year": 2010, "what": "Youngest Everest summiteer (age 13)", "who": "Jordan Romero"}, {"year": 2013, "what": "Oldest Everest summiteer (age 80)", "who": "Yuichiro Miura"}, {"year": 2019, "what": "Fourteen 8,000 m peaks in 6 months and 6 days", "who": "Nirmal Purja"}, {"year": 2021, "what": "First winter ascent of K2", "who": "A team of ten Nepali climbers"}, {"year": 2023, "what": "Fourteen 8,000 m peaks in 92 days", "who": "Kristin Harila, Tenjen Lama Sherpa"}], "current": [{"label": "Most Everest summits", "value": "32", "who": "Kami Rita Sherpa, 17 May 2026"}, {"label": "Most Everest summits by a woman", "value": "11", "who": "Lhakpa Sherpa, 17 May 2026"}, {"label": "Most summits in one day (Nepal side)", "value": "274", "who": "20 May 2026"}, {"label": "Everest permits in one spring", "value": "494", "who": "Spring 2026, a record"}], "disasters": [{"year": 1996, "text": "Eight people die in one storm on 10 and 11 May."}, {"year": 2014, "text": "An avalanche in the Khumbu Icefall kills sixteen Nepali guides on 18 April."}, {"year": 2015, "text": "An earthquake triggers an avalanche that hits Base Camp; at least nineteen people die."}, {"year": 2023, "text": "The deadliest Everest season on record by many counts, with 17 or 18 deaths depending on the source."}]}, "clubs": {"intro": "These are mountaineering clubs and organisations from different regions. Locations are shown at city level. Click a marker or a card to see details, or allow your location to see how far each one is from you.", "clubs": [{"id": "ac-uk", "name": "The Alpine Club", "country": "United Kingdom", "region": "Europe", "city": "London", "lat": 51.5074, "lng": -0.1278, "founded": 1857, "focus": "Oldest mountaineering club in the world. Meets, library and archive, and the Alpine Journal.", "offers": ["Club meets", "Library", "Expedition grants support"], "url": "https://www.alpine-club.org.uk"}, {"id": "sac", "name": "Swiss Alpine Club (SAC)", "country": "Switzerland", "region": "Europe", "city": "Bern", "lat": 46.948, "lng": 7.4474, "founded": 1863, "focus": "A national club that runs a large network of mountain huts across the Swiss Alps.", "offers": ["Mountain huts", "Courses", "Tour guides"], "url": "https://www.sac-cas.ch"}, {"id": "cai", "name": "Club Alpino Italiano (CAI)", "country": "Italy", "region": "Europe", "city": "Milan", "lat": 45.4642, "lng": 9.19, "founded": 1863, "focus": "Italy's national mountaineering club, founded in Turin. Maintains hundreds of huts and paths.", "offers": ["Mountain huts", "Courses", "Trail maintenance"], "url": "https://www.cai.it"}, {"id": "dav", "name": "Deutscher Alpenverein (DAV)", "country": "Germany", "region": "Europe", "city": "Munich", "lat": 48.1351, "lng": 11.582, "founded": 1869, "focus": "One of the largest mountaineering associations in the world, with over a million members.", "offers": ["Mountain huts", "Courses", "Climbing halls"], "url": "https://www.alpenverein.de"}, {"id": "ffcam", "name": "FFCAM (Club Alpin Français)", "country": "France", "region": "Europe", "city": "Paris", "lat": 48.8566, "lng": 2.3522, "founded": 1874, "focus": "The French mountaineering and climbing federation, with huts around Chamonix and the Écrins.", "offers": ["Mountain huts", "Courses", "Group outings"], "url": "https://www.ffcam.fr"}, {"id": "aac", "name": "American Alpine Club", "country": "United States", "region": "Americas", "city": "Golden, Colorado", "lat": 39.7555, "lng": -105.2211, "founded": 1902, "focus": "Publishes the American Alpine Journal and gives grants for climbing expeditions.", "offers": ["Grants", "Rescue insurance", "Huts"], "url": "https://americanalpineclub.org"}, {"id": "acc", "name": "Alpine Club of Canada", "country": "Canada", "region": "Americas", "city": "Canmore, Alberta", "lat": 51.0884, "lng": -115.3479, "founded": 1906, "focus": "Runs backcountry huts and training courses in the Canadian Rockies.", "offers": ["Backcountry huts", "Courses", "Summer camps"], "url": "https://www.alpineclubofcanada.ca"}, {"id": "aai", "name": "Alpine Ascents International", "country": "United States", "region": "Americas", "city": "Seattle, Washington", "lat": 47.6062, "lng": -122.3321, "founded": 1991, "focus": "A guiding company that leads climbs on Rainier, Denali, Aconcagua, Kilimanjaro and Everest.", "offers": ["Guided expeditions", "Training courses"], "url": "https://www.alpineascents.com"}, {"id": "cab", "name": "Club Andino Boliviano", "country": "Bolivia", "region": "Americas", "city": "La Paz", "lat": -16.4897, "lng": -68.1193, "founded": 1939, "focus": "Bolivia's mountaineering club, based in La Paz at around 3,600 m, close to the high Andes.", "offers": ["Andean climbs", "Club meets"], "url": null}, {"id": "nma", "name": "Nepal Mountaineering Association", "country": "Nepal", "region": "Asia", "city": "Kathmandu", "lat": 27.7172, "lng": 85.324, "founded": 1973, "focus": "Represents Nepali mountaineering and issues permits for the trekking peaks.", "offers": ["Trekking peak permits", "Training"], "url": null}, {"id": "hmi", "name": "Himalayan Mountaineering Institute", "country": "India", "region": "Asia", "city": "Darjeeling", "lat": 27.041, "lng": 88.2663, "founded": 1954, "focus": "Founded after the 1953 Everest climb, with Tenzing Norgay as its first director of field training.", "offers": ["Basic and advanced courses", "Museum"], "url": null}, {"id": "imf", "name": "Indian Mountaineering Foundation", "country": "India", "region": "Asia", "city": "New Delhi", "lat": 28.6139, "lng": 77.209, "founded": 1961, "focus": "The national body for mountaineering in India. Organises expeditions and handles peak permits.", "offers": ["Expeditions", "Permits", "Rescue support"], "url": "https://indmount.org"}, {"id": "jac", "name": "Japanese Alpine Club", "country": "Japan", "region": "Asia", "city": "Tokyo", "lat": 35.6762, "lng": 139.6503, "founded": 1905, "focus": "One of Asia's oldest alpine clubs. Japanese teams have a long record in the Himalaya.", "offers": ["Club meets", "Expeditions"], "url": null}, {"id": "acp", "name": "Alpine Club of Pakistan", "country": "Pakistan", "region": "Asia", "city": "Islamabad", "lat": 33.6844, "lng": 73.0479, "founded": null, "focus": "Supports climbing in the Karakoram, home to K2 and three other 8,000 m peaks.", "offers": ["Karakoram expeditions", "Permits"], "url": null}, {"id": "mcsa", "name": "Mountain Club of South Africa", "country": "South Africa", "region": "Africa", "city": "Cape Town", "lat": -33.9249, "lng": 18.4241, "founded": 1891, "focus": "Climbing, hiking and mountain rescue around Table Mountain and the Drakensberg.", "offers": ["Rescue", "Courses", "Club meets"], "url": "https://mcsa.org.za"}, {"id": "mck", "name": "Mountain Club of Kenya", "country": "Kenya", "region": "Africa", "city": "Nairobi", "lat": -1.2921, "lng": 36.8219, "founded": 1949, "focus": "Climbs on Mount Kenya, Kilimanjaro and Rift Valley crags.", "offers": ["Climbs", "Courses"], "url": null}, {"id": "nzac", "name": "New Zealand Alpine Club", "country": "New Zealand", "region": "Oceania", "city": "Christchurch", "lat": -43.5321, "lng": 172.6362, "founded": 1891, "focus": "Backcountry huts and mountaineering in the Southern Alps, the training ground of Edmund Hillary.", "offers": ["Huts", "Courses", "Club trips"], "url": null}]}, "stories": {"intro": "Big climbs are team efforts. These are some that worked, and what each one teaches.", "stories": [{"year": 1953, "title": "The first ascent of Everest", "org": "British Everest Expedition, led by John Hunt", "place": "Nepal", "img": "assets/img/everest-dawn.svg", "text": "A big team of climbers, Sherpa and porters set up a chain of camps. Hunt chose two summit pairs. The first pair turned back, exhausted. On 29 May Hillary and Tenzing reached the top and spent about fifteen minutes there.", "lesson": "Preparation and teamwork put two people on the summit. Everyone on that expedition had a part in it."}, {"year": 1955, "title": "Stopping short on Kangchenjunga", "org": "British Kangchenjunga Expedition, led by Charles Evans", "place": "Nepal / India", "img": "assets/img/prayer-flags.svg", "text": "Joe Brown and George Band climbed to within a few steps of the summit and stopped. They had promised the Sikkimese that they would not set foot on the top, which the local people hold sacred. The tradition of leaving the final few metres has been kept by many climbers since.", "lesson": "Respect for local belief is part of the job. It also shows that a summit is not the only measure of a climb."}, {"year": 1975, "title": "Junko Tabei on Everest", "org": "Ladies' Climbing Club, Japan", "place": "Nepal", "img": "assets/img/summit-ridge.svg", "text": "An avalanche buried Tabei at Camp II on 4 May. Sherpa guides dug her out. Twelve days later, on 16 May, she walked to the top, the first woman to stand on Everest.", "lesson": "Good teams look after each other, and a bad day does not have to end an expedition."}, {"year": 1978, "title": "Everest with no bottled oxygen", "org": "Austrian Everest expedition", "place": "Nepal", "img": "assets/img/k2-storm.svg", "text": "Reinhold Messner and Peter Habeler reached the top on 8 May. Habeler was worried that the thin air would damage his brain, so he descended very quickly. Both were fine. The climb changed what people believed was possible.", "lesson": "Limits that experts accept as fixed sometimes turn out to be assumptions."}, {"year": 1984, "title": "Bachendri Pal, first Indian woman on Everest", "org": "Indian Mountaineering Foundation", "place": "Nepal", "img": "assets/img/aconcagua-dusk.svg", "text": "Bachendri Pal reached the summit on 23 May 1984 as part of an Indian expedition. She went on to encourage many women to take up climbing in India.", "lesson": "One visible success can open a whole sport to people who had been left out."}, {"year": 2019, "title": "Project Possible", "org": "Nirmal Purja and a Nepali team", "place": "Nepal, Pakistan, Tibet", "img": "assets/img/denali-aurora.svg", "text": "Purja climbed all fourteen 8,000 m peaks in six months and six days. The previous record was close to eight years. The climb needed support from teammates and arranged flights and permits.", "lesson": "Logistics and planning matter as much as strength."}, {"year": 2021, "title": "K2 in winter", "org": "Ten Nepali climbers", "place": "Pakistan", "img": "assets/img/matterhorn-noon.svg", "text": "K2 was the only 8,000 m peak never climbed in winter. On 16 January ten Nepali climbers took the last steps together to the top, in temperatures reported to be around minus 60 °C.", "lesson": "Sherpa and Nepali climbers carry the work on these peaks, and this climb finally put them in front."}]}, "gallery": {"intro": "Illustrations of the places and moments this site is about, and a few short explainer videos made for the project.", "pictures": [{"file": "everest-dawn.svg", "title": "Everest at dawn", "cat": "Peaks", "caption": "The summit pyramid catching the first light."}, {"file": "k2-storm.svg", "title": "K2 as the storm builds", "cat": "Peaks", "caption": "Weather turns quickly in the Karakoram."}, {"file": "matterhorn-noon.svg", "title": "A pyramid peak in clear weather", "cat": "Peaks", "caption": "A rope team heading for the summit ridge."}, {"file": "denali-aurora.svg", "title": "Denali and the northern lights", "cat": "Peaks", "caption": "Night over the Alaska Range."}, {"file": "aconcagua-dusk.svg", "title": "Aconcagua at dusk", "cat": "Peaks", "caption": "The highest peak in the Andes."}, {"file": "kilimanjaro.svg", "title": "Kilimanjaro at sunrise", "cat": "Peaks", "caption": "A mountain you can climb without technical skills."}, {"file": "summit-ridge.svg", "title": "Climbers on the summit ridge", "cat": "Climbing", "caption": "Roped together on the last stretch."}, {"file": "ice-climbing.svg", "title": "Ice climbing", "cat": "Climbing", "caption": "Two tools, two crampons, and a lot of calf muscle."}, {"file": "glacier-team.svg", "title": "Crossing a glacier", "cat": "Climbing", "caption": "A rope team steps around a crevasse."}, {"file": "high-camp.svg", "title": "High camp at dusk", "cat": "Camps and huts", "caption": "Tents on a snow platform."}, {"file": "mountain-hut.svg", "title": "Mountain hut at night", "cat": "Camps and huts", "caption": "Warm light in a cold valley."}, {"file": "prayer-flags.svg", "title": "Prayer flags", "cat": "Culture", "caption": "Flags strung above a Himalayan valley."}, {"file": "history-engraving.svg", "title": "An old-style engraving", "cat": "Culture", "caption": "Early climbers drew the Alps like this."}], "videos": [{"file": "altitude.mp4", "poster": "altitude.jpg", "title": "How thin does the air get?", "text": "A 15 second look at how much oxygen is available at different heights, from sea level to the top of Everest.", "length": "0:15"}, {"file": "route.mp4", "poster": "route.jpg", "title": "Everest South Col route", "text": "The camps on the standard Nepal-side route and the height of each, from Base Camp to the summit.", "length": "0:16"}, {"file": "sevensummits.mp4", "poster": "sevensummits.jpg", "title": "The Seven Summits", "text": "The highest peak on each continent, drawn to scale against each other.", "length": "0:14"}], "watch": [{"title": "Everest: 50 Years on the Mountain", "by": "National Geographic, 2003", "q": "Everest 50 Years on the Mountain National Geographic documentary"}, {"title": "Lost on Everest", "by": "National Geographic, 2020", "q": "Lost on Everest National Geographic Mallory Irvine documentary"}, {"title": "Climbing Everest with a Mountain on My Back", "by": "BBC", "q": "Climbing Everest with a Mountain on My Back BBC"}, {"title": "Mountain Queen: The Summits of Lhakpa Sherpa", "by": "Netflix, 2022", "q": "Mountain Queen Summits of Lhakpa Sherpa documentary"}]}, "news": {"intro": "A few things that have changed in the last couple of years. Check the sources linked on each item for full details.", "asOf": "October 2026", "items": [{"date": "2026-05-24", "tag": "Season", "title": "Busiest Everest spring season on record", "text": "By 24 May, 879 climbers and guides had reached the summit from the Nepal side, with roughly 75 more expected, and a record 494 permits had been issued. A record 274 people summited on a single day, 20 May.", "source": "Everest Chronicle", "url": "https://everestchronicle.com/everest-records-busiest-spring-climbing-season-on-record"}, {"date": "2026-05-17", "tag": "Records", "title": "Kami Rita Sherpa climbs Everest for the 32nd time", "text": "Kami Rita extended his own record on 17 May. On the same day Lhakpa Sherpa reached the top for the 11th time, the most for any woman.", "source": "Nepal Department of Tourism", "url": "https://tourismdepartment.gov.np/content/168/press-release-on-everest-history-rewritten--32/"}, {"date": "2026-03-24", "tag": "Rules", "title": "New Khumbu Icefall fee and stricter waste rules", "text": "Foreign climbers on Everest, Lhotse and Nuptse pay a $600 icefall route fee from spring 2026. Waste rules now ask climbers to bring down 8 kg of rubbish, at least 2 kg of it from above Camp II.", "source": "Nepal Traveller", "url": "https://nepaltraveller.com/news/everest-climbers-face-600-khumbu-icefall-fee-as-waste-rules-tighten-at-base-camp"}, {"date": "2026-02-19", "tag": "Sport", "title": "Ski mountaineering makes its Olympic debut", "text": "Skimo was added to the Winter Olympics in Milan Cortina, with races in Bormio, Italy. Marianne Fatton of Switzerland and Oriol Cardona Coll of Spain won the first sprint titles.", "source": "NBC Olympics", "url": "https://www.nbcolympics.com/news/ski-mountaineering-2026-milan-cortina-winter-olympics"}, {"date": "2025-01-01", "dateLabel": "2025", "tag": "Rules", "title": "Everest permit fee rises to $15,000", "text": "The fee for foreign climbers on the Nepal side went up from $11,000 to $15,000.", "source": "Everest Chronicle", "url": "https://everestchronicle.com/everest-records-busiest-spring-climbing-season-on-record"}, {"date": "2024-03-07", "tag": "Safety", "title": "GPS tracking chips become compulsory on Everest", "text": "After a deadly 2023 season, Nepal's tourism department made tracking chips or GPS devices mandatory for climbers and guides, to make search and rescue quicker.", "source": "The Kathmandu Post", "url": "https://kathmandupost.com/money/2024/03/07/tracking-chip-now-mandatory-for-everest-aspirants"}], "trends": [{"title": "More rules, fewer shortcuts", "text": "Nepal has been tightening requirements around permits, tracking and waste. Reports also mention an experience requirement for Everest climbers; check the Department of Tourism for the current text before you plan a trip."}, {"title": "Crowding", "text": "Record permit numbers mean queues at the Hillary Step area and long waits at the top in good-weather windows. Guides argue for staggering summit days."}, {"title": "Cleaner mountains", "text": "Clean-up expeditions and 'carry out what you carry in' rules are now standard on the Nepal side."}, {"title": "Technology", "text": "Better forecasting, satellite messengers and lighter kit have changed how teams plan, though none of them replaces experience."}]}, "guidelines": {"intro": "A plain checklist for planning a first serious mountain trip. It is not a replacement for a course or a guide.", "sections": [{"title": "Before you go", "icon": "bi-calendar-check", "items": ["Get fit for the trip you are planning. Long days with a loaded pack are the best training.", "Take a course in basic mountaineering skills: ropework, crampons, ice axe and self-arrest.", "Start on easy peaks and build up. Do not jump to a big mountain on your first trip.", "See a doctor, especially if you have a heart or lung condition, and get your vaccinations.", "Buy travel insurance that covers rescue at the altitude you will be at."]}, {"title": "What to carry", "icon": "bi-backpack", "items": ["Map, compass and a charged phone or GPS.", "Head torch with spare batteries.", "Sun protection: glacier glasses, sun cream and a hat.", "First aid kit and a bivouac sack or emergency blanket.", "Enough food and water, plus a spare day of food.", "Extra layers, hat, gloves and a waterproof shell."]}, {"title": "On the mountain", "icon": "bi-signpost-split", "items": ["Tell somebody your plan and when you expect to be back.", "Check the forecast the night before and again in the morning.", "Set a turnaround time and keep to it, whatever the weather looks like.", "Eat and drink little and often.", "Watch your partners, and speak up if someone looks unwell."]}, {"title": "Respect", "icon": "bi-heart", "items": ["Leave no trace. Carry your rubbish down, including human waste where it is required.", "Respect local customs and sacred peaks.", "Pay guides, porters and cooks fairly, and make sure they have proper kit and insurance.", "Do not leave fixed ropes or gear behind.", "Follow permit rules for the country you are in."]}], "essentials": ["Navigation", "Sun protection", "Insulation", "Illumination", "First aid supplies", "Fire", "Repair kit and tools", "Nutrition", "Hydration", "Emergency shelter"]}};
